{"path": "two_bucket.py", "content": "from collections import deque


def measure(bucket_one, bucket_two, goal, start_bucket):
    if start_bucket not in ("one", "two"):
        raise ValueError("start_bucket must be 'one' or 'two'")
    if goal > max(bucket_one, bucket_two):
        raise ValueError("goal is larger than both buckets")
    caps = (bucket_one, bucket_two)
    s = 0 if start_bucket == "one" else 1
    start = (bucket_one, 0) if s == 0 else (0, bucket_two)
    # forbidden: starting bucket empty and other full
    def forbidden(st):
        return st[s] == 0 and st[1 - s] == caps[1 - s]

    seen = {start}
    queue = deque([(start, 1)])
    while queue:
        (a, b), n = queue.popleft()
        if a == goal:
            return (n, "one", b)
        if b == goal:
            return (n, "two", a)
        pour_ab = min(a, bucket_two - b)
        pour_ba = min(b, bucket_one - a)
        for nxt in (
            (bucket_one, b), (a, bucket_two), (0, b), (a, 0),
            (a - pour_ab, b + pour_ab), (a + pour_ba, b - pour_ba),
        ):
            if nxt not in seen and not forbidden(nxt):
                seen.add(nxt)
                queue.append((nxt, n + 1))
    raise ValueError("goal cannot be reached with these buckets")
